// Transforme les résultats de l'annuaire en lignes pour la plateforme
const recherche = $('Recherche en attente').first().json;
const pages = $input.all().map((i) => i.json);

const probleme = pages.find((p) => p.error);
if (probleme) {
  const e = probleme.error;
  return [{ json: { p_recherche_id: recherche.id, p_erreur: "Annuaire des entreprises indisponible : " + (e.message || e.description || JSON.stringify(e)).slice(0, 300) } }];
}

const EFFECTIFS = {
  '00': '0 salarié', '01': '1 à 2 salariés', '02': '3 à 5 salariés', '03': '6 à 9 salariés',
  '11': '10 à 19 salariés', '12': '20 à 49 salariés', '21': '50 à 99 salariés', '22': '100 à 199 salariés',
  '31': '200 à 249 salariés', '32': '250 à 499 salariés', '41': '500 à 999 salariés',
  '42': '1 000 à 1 999 salariés', '51': '2 000 à 4 999 salariés', '52': '5 000 à 9 999 salariés', '53': '10 000 salariés et plus',
};
// "CABINET DUPONT ET ASSOCIES (CDA)" -> "Cabinet Dupont et Associes"
const PETITS_MOTS = new Set(['et', 'de', 'du', 'des', 'la', 'le', 'les', 'en', 'sur', 'au', 'aux', 'a', 'à']);
const joli = (s) => String(s || '')
  .replace(/\s*\([^)]*\)\s*$/, '')
  .toLowerCase()
  .replace(/(^|[\s'’(\-\/])(\p{L}+)/gu, (m, a, mot) => a + (a && a.trim() === '' && PETITS_MOTS.has(mot) ? mot : mot[0].toUpperCase() + mot.slice(1)))
  .trim();

const voulu = Math.min(Number(recherche.nombre) || 25, 200);
const lignes = [];
const vus = new Set();
for (const page of pages) {
  for (const e of page.results || []) {
    if (lignes.length >= voulu) break;
    if (!e.siren || vus.has(e.siren)) continue;
    vus.add(e.siren);
    const siege = e.siege || {};
    const dirigeant = (e.dirigeants || []).find((d) => d.type_dirigeant === 'personne physique' && d.nom);
    const prenom = dirigeant && dirigeant.prenoms ? String(dirigeant.prenoms).split(/[\s,]+/)[0] : '';
    lignes.push({
      siren: e.siren,
      entreprise: joli(e.nom_complet || e.nom_raison_sociale),
      ville: joli(siege.libelle_commune),
      effectif: EFFECTIFS[e.tranche_effectif_salarie || siege.tranche_effectif_salarie] || null,
      contact_nom: dirigeant ? joli((prenom + ' ' + dirigeant.nom).trim()) : null,
      contact_poste: dirigeant ? dirigeant.qualite || null : null,
    });
  }
}

return [{ json: {
  p_recherche_id: recherche.id,
  p_lignes: lignes,
  p_nb_trouvees: pages[0] && pages[0].total_results != null ? pages[0].total_results : lignes.length,
} }];
